input.content:
/* ============================================================
   NABER — interface system
   ============================================================ */
:root{
  --bg:#05060d;
  --ink:#eafff4;
  --dim:#8da39e;
  --lime:#caff4a;
  --lime-soft:#e5ff9c;
  --cyan:#55f2ff;
  --magenta:#ff4f9e;
  --gold:#ffd35c;
  --violet:#7a5cff;
  --line:rgba(202,255,74,.16);
  --glass:rgba(9,14,22,.72);
  --ui-font:"Lato","Helvetica Neue",Arial,sans-serif;
  --mono:"DejaVu Sans Mono",ui-monospace,"SF Mono",Menlo,monospace;
}
*{box-sizing:border-box}
html,body{height:100%}
html{background:var(--bg);}
body{
  margin:0;overflow:hidden;background:var(--bg);color:var(--ink);
  font-family:var(--ui-font);font-weight:400;
  -webkit-font-smoothing:antialiased;
  -webkit-tap-highlight-color:transparent;
  overscroll-behavior:none;
  user-select:none;-webkit-user-select:none;
  touch-action:none;
}
button{font-family:inherit;color:inherit;border:0;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent}
b{font-weight:900}
.hidden{display:none!important}

#app{position:fixed;inset:0;overflow:hidden;isolation:isolate}
#stage{
  position:absolute;inset:0;width:100%;height:100%;display:block;
  touch-action:none;cursor:crosshair;outline:none;
}
#grain{
  position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.055;
  background-image:repeating-linear-gradient(0deg,rgba(255,255,255,.7) 0 1px,transparent 1px 3px);
  mix-blend-mode:screen;
}
#vignette{
  position:absolute;inset:0;pointer-events:none;z-index:3;
  background:
    radial-gradient(ellipse at 50% 48%,transparent 42%,rgba(2,3,8,.42) 78%,rgba(2,3,8,.86) 100%),
    linear-gradient(180deg,rgba(3,5,10,.5),transparent 16%,transparent 82%,rgba(3,5,10,.5));
}
#edge-warning{
  position:absolute;inset:0;pointer-events:none;z-index:4;opacity:0;transition:opacity .18s;
  background:radial-gradient(ellipse at 50% 50%,transparent 48%,rgba(255,46,130,.24) 88%,rgba(255,46,130,.5) 100%);
  box-shadow:inset 0 0 120px 20px rgba(255,40,120,.28);
}
#edge-warning.on{opacity:1;animation:edgePulse .8s ease-in-out infinite}
@keyframes edgePulse{0%,100%{opacity:.45}50%{opacity:1}}

/* ---------------- HUD ---------------- */
#hud{
  position:absolute;inset:0;z-index:6;pointer-events:none;
  padding:calc(16px + env(safe-area-inset-top)) calc(18px + env(safe-area-inset-right)) 16px calc(18px + env(safe-area-inset-left));
  display:flex;justify-content:space-between;align-items:flex-start;
  font-family:var(--mono);
}
.hud-left{display:flex;flex-direction:column;gap:8px;align-items:flex-start}
.hud-wave{display:flex;align-items:center;gap:9px;font-size:10px;letter-spacing:.2em;color:var(--lime);text-transform:uppercase}
.hud-rule{display:block;width:26px;height:1px;background:linear-gradient(90deg,var(--lime),transparent)}
#wave-name{color:var(--dim);letter-spacing:.18em}
.hud-hearts{display:flex;gap:6px;align-items:center;height:14px}
.heart{width:15px;height:15px;position:relative;transform:rotate(45deg);border:1px solid rgba(202,255,74,.55);border-radius:3px 50% 50% 50%;background:rgba(202,255,74,.12);transition:.25s}
.heart.full{background:var(--lime);border-color:var(--lime);box-shadow:0 0 12px rgba(202,255,74,.5)}
.heart.empty{opacity:.32;background:transparent}
.heart.pulse{animation:heartPulse .5s ease-out}
@keyframes heartPulse{0%{transform:rotate(45deg) scale(1.5)}100%{transform:rotate(45deg) scale(1)}}
.hud-goal{font-size:11px;letter-spacing:.1em;color:var(--ink);margin-top:2px}
.hud-goal .slash{color:var(--dim);margin:0 2px}
.hud-goal .label{margin-left:7px;font-size:8px;letter-spacing:.22em;color:var(--dim)}
.hud-right{text-align:right;display:flex;flex-direction:column;align-items:flex-end}
.hud-score-label{font-size:8px;letter-spacing:.3em;color:var(--dim)}
.hud-score{
  font-size:clamp(24px,3.4vw,38px);line-height:1;font-weight:400;letter-spacing:.02em;
  color:var(--ink);text-shadow:0 0 22px rgba(85,242,255,.35);
  font-variant-numeric:tabular-nums;min-width:120px;
}
.hud-best{font-size:8px;letter-spacing:.22em;color:var(--dim);margin-top:5px}
.hud-best span{color:var(--lime)}
.hud-buttons{
  position:absolute;z-index:9;top:calc(14px + env(safe-area-inset-top));
  left:50%;transform:translateX(-50%);display:flex;gap:8px;
}
.icon-btn{
  width:38px;height:38px;border-radius:50%;display:grid;place-items:center;
  background:rgba(7,12,18,.5);border:1px solid rgba(202,255,74,.18);
  backdrop-filter:blur(8px);color:var(--dim);transition:.18s;
}
.icon-btn:hover{border-color:rgba(202,255,74,.5);color:var(--lime);background:rgba(202,255,74,.08)}
.icon-btn:active{transform:scale(.94)}
.icon-btn svg{width:16px;height:16px;fill:currentColor}
.icon-btn .slash{display:none;stroke:currentColor;stroke-width:2;fill:none;stroke-linecap:round}
body.muted #mute-btn .wave,body.muted #mute-btn .wave2{display:none}
body.muted #mute-btn .slash{display:block}

#combo{
  position:absolute;left:50%;bottom:calc(28px + env(safe-area-inset-bottom));transform:translateX(-50%);
  z-index:7;pointer-events:none;width:172px;text-align:center;
}
.combo-row{display:flex;align-items:baseline;justify-content:center;gap:8px}
#combo-x{
  font-family:var(--mono);font-size:26px;font-weight:700;color:var(--lime);
  text-shadow:0 0 24px rgba(202,255,74,.55);letter-spacing:-.04em;
}
#combo-label{font-family:var(--mono);font-size:8px;letter-spacing:.32em;color:var(--dim)}
.combo-bar{height:2px;margin-top:6px;background:rgba(255,255,255,.08);overflow:hidden}
#combo-fill{display:block;height:100%;width:100%;background:linear-gradient(90deg,var(--lime),var(--cyan));transform-origin:left;}

#surge-meter{
  position:absolute;left:50%;top:calc(64px + env(safe-area-inset-top));transform:translateX(-50%);
  z-index:7;pointer-events:none;display:flex;flex-direction:column;align-items:center;gap:4px;
  font-family:var(--mono);font-size:8px;letter-spacing:.3em;color:var(--gold);
  filter:drop-shadow(0 0 10px rgba(255,211,92,.5));
}
.surge-bar{width:110px;height:2px;background:rgba(255,211,92,.16)}
#surge-fill{display:block;height:100%;width:100%;background:var(--gold);transform-origin:left}

#banner{
  position:absolute;left:50%;top:32%;transform:translate(-50%,-50%);
  z-index:8;pointer-events:none;text-align:center;opacity:0;width:min(92vw,600px);
}
#banner.show{animation:bannerIn 2.1s cubic-bezier(.2,.8,.2,1) forwards}
@keyframes bannerIn{
  0%{opacity:0;transform:translate(-50%,-46%)}
  10%,72%{opacity:1;transform:translate(-50%,-50%)}
  100%{opacity:0;transform:translate(-50%,-54%)}
}
.banner-kicker{font-family:var(--mono);font-size:9px;letter-spacing:.45em;color:var(--cyan);margin-bottom:8px;text-transform:uppercase}
.banner-title{
  font-weight:900;font-size:clamp(30px,6.4vw,58px);line-height:.95;letter-spacing:.02em;
  text-transform:uppercase;color:var(--ink);text-shadow:0 0 34px rgba(85,242,255,.35);
}
.banner-sub{font-family:var(--mono);font-size:10px;letter-spacing:.24em;color:var(--dim);margin-top:10px;text-transform:uppercase}

#hint{
  position:absolute;left:50%;bottom:calc(86px + env(safe-area-inset-bottom));transform:translateX(-50%);
  z-index:7;pointer-events:none;font-family:var(--mono);font-size:9px;letter-spacing:.18em;
  color:rgba(234,255,244,.66);background:rgba(5,8,14,.55);border:1px solid rgba(202,255,74,.16);
  padding:8px 14px;border-radius:99px;backdrop-filter:blur(6px);white-space:nowrap;
  animation:hintBob 2.4s ease-in-out infinite;
}
@keyframes hintBob{0%,100%{transform:translate(-50%,0)}50%{transform:translate(-50%,-4px)}}

/* ---------------- screens ---------------- */
.screen{
  position:absolute;inset:0;z-index:20;display:grid;place-items:center;
  padding:calc(22px + env(safe-area-inset-top)) 20px calc(22px + env(safe-area-inset-bottom));
  background:radial-gradient(ellipse at 50% 46%,rgba(5,7,14,.24),rgba(2,3,8,.82) 74%);
  backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px);
  animation:screenIn .45s ease-out both;
}
@keyframes screenIn{from{opacity:0}to{opacity:1}}
.menu-scrim{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(3,5,10,.18),rgba(3,5,10,.65))}
.menu-frame{position:relative;width:min(720px,94vw);display:flex;flex-direction:column;align-items:center;text-align:center}
.brand-row{
  width:100%;display:flex;align-items:center;gap:14px;justify-content:center;
  font-family:var(--mono);font-size:8px;letter-spacing:.34em;color:rgba(141,163,158,.75);
  margin-bottom:clamp(18px,4vh,34px);text-transform:uppercase;
}
.brand-line{width:64px;height:1px;background:linear-gradient(90deg,transparent,rgba(202,255,74,.45),transparent)}
.title-wrap{position:relative;padding:0 10px;margin-bottom:6px}
.title-shadow{
  position:absolute;left:50%;top:52%;transform:translate(-50%,-50%);
  font-weight:900;font-size:clamp(82px,20vw,178px);letter-spacing:.015em;line-height:.8;
  color:transparent;-webkit-text-stroke:1px rgba(85,242,255,.18);
  filter:blur(.4px);user-select:none;
}
.title{
  position:relative;margin:0;font-weight:900;
  font-size:clamp(78px,19vw,170px);line-height:.8;letter-spacing:.015em;
  background:linear-gradient(180deg,#f4ffe4 4%,#d4ff74 38%,#8bff9b 63%,#55f2ff 120%);
  -webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 0 28px rgba(202,255,74,.22)) drop-shadow(0 6px 0 rgba(0,0,0,.25));
}
.title::after{
  content:"NABER";position:absolute;left:0;top:0;color:transparent;
  -webkit-text-stroke:1px rgba(10,20,12,.55);z-index:-1;transform:translate(5px,6px);
}
.title-sub{
  font-family:var(--mono);font-size:clamp(8px,1.5vw,11px);letter-spacing:.62em;
  color:var(--lime);margin-top:18px;text-indent:.62em;opacity:.92;
}
.pitch{
  margin:clamp(20px,4vh,34px) auto clamp(22px,4vh,32px);max-width:46ch;
  font-size:clamp(13px,1.9vw,16px);line-height:1.65;color:rgba(205,224,216,.82);font-weight:400;
}
.pitch .br-sm{display:block}
.cta{
  position:relative;display:inline-flex;align-items:center;justify-content:center;gap:14px;
  min-height:56px;padding:0 34px;border-radius:99px;overflow:hidden;
  background:var(--lime);color:#0a1206;font-weight:900;font-size:13px;letter-spacing:.22em;
  box-shadow:0 0 0 1px rgba(255,255,255,.2) inset,0 8px 34px rgba(202,255,74,.22),0 2px 0 rgba(0,0,0,.3);
  transition:transform .18s cubic-bezier(.2,.8,.2,1),box-shadow .18s,filter .18s;
}
.cta::before{
  content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.55) 48%,transparent 66%);
  transform:translateX(-120%);transition:transform .6s ease;
}
.cta:hover{transform:translateY(-2px);box-shadow:0 0 0 1px rgba(255,255,255,.35) inset,0 12px 46px rgba(202,255,74,.36),0 2px 0 rgba(0,0,0,.3)}
.cta:hover::before{transform:translateX(120%)}
.cta:active{transform:translateY(1px) scale(.99)}
.cta:focus-visible{outline:2px solid var(--cyan);outline-offset:4px}
.cta .cta-dot{width:7px;height:7px;border-radius:50%;background:#0a1206;box-shadow:0 0 0 3px rgba(10,18,6,.18);animation:dotPulse 1.8s ease-in-out infinite}
@keyframes dotPulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.4;transform:scale(.72)}}
.cta .cta-key{font-family:var(--mono);font-weight:400;font-size:10px;opacity:.55;letter-spacing:0}
.cta.small{min-height:50px;padding:0 26px;font-size:11px}
.control-strip{
  display:flex;gap:clamp(14px,3vw,34px);flex-wrap:wrap;justify-content:center;
  margin-top:clamp(24px,5vh,40px);font-family:var(--mono);font-size:9px;letter-spacing:.12em;color:var(--dim);
}
.control{display:flex;align-items:center;gap:9px}
.control b{color:var(--ink);font-weight:700}
.glyph{width:20px;height:20px;border:1px solid rgba(202,255,74,.4);border-radius:50%;position:relative;flex:none}
.glyph-hold::after{content:"";position:absolute;inset:6px;border-radius:50%;background:var(--lime)}
.glyph-release::after{content:"";position:absolute;left:50%;top:50%;width:7px;height:7px;border-radius:50%;background:var(--lime);transform:translate(-50%,-50%)}
.glyph-release::before{content:"";position:absolute;inset:3px;border-radius:50%;border:1px dashed rgba(202,255,74,.5);animation:spin 8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.key{font-family:var(--mono);font-size:8px;border:1px solid rgba(202,255,74,.35);border-radius:4px;padding:3px 6px;color:var(--lime)}
.menu-foot{
  margin-top:clamp(24px,5vh,38px);padding-top:16px;width:min(440px,80vw);
  border-top:1px solid rgba(202,255,74,.14);
  display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;
  font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:rgba(141,163,158,.7);
}
.menu-foot b{color:var(--lime);font-weight:400}
.menu-foot .dot{width:3px;height:3px;border-radius:50%;background:rgba(202,255,74,.4)}

.panel{
  position:relative;width:min(520px,92vw);padding:clamp(26px,5vw,44px);
  background:linear-gradient(160deg,rgba(10,16,24,.92),rgba(5,8,14,.9));
  border:1px solid rgba(202,255,74,.18);border-radius:2px;
  box-shadow:0 40px 100px rgba(0,0,0,.6),0 0 70px rgba(202,255,74,.05) inset;
  text-align:center;overflow:hidden;
}
.panel::before{content:"";position:absolute;left:0;right:0;top:0;height:2px;background:linear-gradient(90deg,transparent,var(--lime),var(--cyan),transparent);opacity:.7}
.panel::after{content:"";position:absolute;width:120px;height:120px;right:-40px;top:-40px;border:1px solid rgba(85,242,255,.14);transform:rotate(45deg);pointer-events:none}
.panel-kicker{font-family:var(--mono);font-size:8px;letter-spacing:.4em;color:var(--cyan);margin-bottom:10px}
.panel h2{
  margin:0 0 24px;font-weight:900;font-size:clamp(32px,6vw,48px);line-height:.92;letter-spacing:.02em;
  text-transform:uppercase;background:linear-gradient(180deg,#f2ffe2,#caff4a 70%,#7dffb0);
  -webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 0 22px rgba(202,255,74,.2));
}
.over-panel h2{font-size:clamp(28px,5.4vw,42px)}
.stat-row{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;margin:22px 0;border:1px solid rgba(202,255,74,.13);background:rgba(202,255,74,.03)}
.stat-row>div{padding:10px 6px;border-right:1px solid rgba(202,255,74,.1)}
.stat-row>div:last-child{border-right:0}
.stat-row span{display:block;font-family:var(--mono);font-size:7px;letter-spacing:.26em;color:var(--dim);margin-bottom:5px}
.stat-row b{font-family:var(--mono);font-size:16px;font-weight:400;color:var(--ink)}
.panel-controls{text-align:left;font-size:12px;line-height:1.6;color:rgba(205,224,216,.78);margin:0 0 24px;display:grid;gap:8px}
.panel-controls p{margin:0}
.panel-controls b{color:var(--lime)}
.btn-row{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:6px}
.ghost{
  min-height:50px;padding:0 22px;border:1px solid rgba(202,255,74,.25);border-radius:99px;
  font-size:10px;letter-spacing:.2em;color:var(--dim);transition:.18s;font-weight:700;
}
.ghost:hover{color:var(--ink);border-color:rgba(202,255,74,.55);background:rgba(202,255,74,.05)}
.ghost:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}
.final-score-wrap{position:relative;margin:4px 0 20px}
.final-score-label{font-family:var(--mono);font-size:7px;letter-spacing:.34em;color:var(--dim);margin-bottom:2px}
.final-score{
  font-family:var(--mono);font-size:clamp(52px,11vw,76px);line-height:1;font-weight:400;
  color:var(--ink);text-shadow:0 0 38px rgba(85,242,255,.45);
  font-variant-numeric:tabular-nums;letter-spacing:-.05em;
}
.new-best{
  display:inline-block;margin-top:8px;font-family:var(--mono);font-size:8px;letter-spacing:.32em;
  color:var(--gold);border:1px solid rgba(255,211,92,.4);padding:4px 9px;border-radius:2px;
  animation:newBest 1.4s ease-in-out infinite;
}
@keyframes newBest{0%,100%{box-shadow:0 0 0 rgba(255,211,92,0)}50%{box-shadow:0 0 24px rgba(255,211,92,.22)}}

#rotate-hint{
  position:fixed;z-index:30;top:calc(10px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);
  font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--gold);
  background:rgba(8,10,16,.8);border:1px solid rgba(255,211,92,.3);padding:6px 10px;border-radius:99px;
}
@media (max-width:520px){
  .desktop-only{display:none}
  .control-strip{gap:12px;font-size:8px}
  .pitch{font-size:12.5px;line-height:1.55;margin:18px auto 20px}
  .title-sub{letter-spacing:.4em;text-indent:.4em}
  .panel{padding:24px 20px}
  .stat-row b{font-size:14px}
  .hud-score{min-width:84px;font-size:24px}
  .hud-left{gap:6px}
  .hud-buttons{top:auto;bottom:calc(12px + env(safe-area-inset-bottom));left:auto;right:calc(16px + env(safe-area-inset-right));transform:none}
  #combo{bottom:calc(20px + env(safe-area-inset-bottom))}
  #hint{bottom:calc(74px + env(safe-area-inset-bottom));font-size:8px}
  .hud-buttons .icon-btn{width:34px;height:34px}
}
@media (max-height:620px){
  .brand-row{margin-bottom:10px}
  .title{font-size:clamp(56px,14vh,110px)}
  .title-shadow{font-size:clamp(56px,14vh,110px)}
  .pitch{margin:12px auto 16px;line-height:1.45;font-size:12px}
  .control-strip{margin-top:16px}
  .menu-foot{margin-top:14px}
  .cta{min-height:48px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001s!important;animation-iteration-count:1!important;transition-duration:.001s!important}
}

// ============================================================
// NABER — procedural audio. No samples, no downloads.
// ============================================================
const PENTA = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24, 26, 28, 31, 33, 36];

function midi(n) { return 440 * Math.pow(2, (n - 69) / 12); }

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicBus = null;
    this.sfxBus = null;
    this.delay = null;
    this.noiseBuf = null;
    this.ready = false;
    this.muted = false;
    this.musicOn = false;
    this.intensity = 0;
    this.step = 0;
    this.nextNote = 0;
    this.pad = null;
  }

  init() {
    if (this.ready) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = this.ctx = new AC();
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.62;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16; comp.knee.value = 22; comp.ratio.value = 5;
    comp.attack.value = 0.004; comp.release.value = 0.24;
    this.master.connect(comp).connect(ctx.destination);

    this.musicBus = ctx.createGain();
    this.musicBus.gain.value = 0.5;
    this.musicBus.connect(this.master);
    this.sfxBus = ctx.createGain();
    this.sfxBus.gain.value = 1;
    this.sfxBus.connect(this.master);

    // echo send for chimes
    this.delay = ctx.createDelay(0.8);
    this.delay.delayTime.value = 0.26;
    const fb = ctx.createGain(); fb.gain.value = 0.26;
    const wet = ctx.createGain(); wet.gain.value = 0.32;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 2600;
    this.delay.connect(lp).connect(fb).connect(this.delay);
    lp.connect(wet).connect(this.master);

    const len = Math.floor(ctx.sampleRate * 1.4);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuf = buf;

    this.ready = true;
    this.buildPad();
  }

  setMuted(m) {
    this.muted = m;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(m ? 0 : 0.62, this.ctx.currentTime, 0.05);
    }
  }

  // ---------- primitives ----------
  tone({ freq = 440, dur = 0.3, type = 'sine', gain = 0.2, slide = 0, when = 0, attack = 0.005, filter = 0, send = 0, detune = 0 }) {
    if (!this.ready || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    if (detune) o.detune.value = detune;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    let node = o;
    if (filter) {
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass'; f.frequency.value = filter;
      node.connect(f); node = f;
    }
    node.connect(g);
    g.connect(this.sfxBus);
    if (send) { const s = ctx.createGain(); s.gain.value = send; g.connect(s).connect(this.delay); }
    o.start(t); o.stop(t + dur + 0.05);
  }

  noise({ dur = 0.3, gain = 0.15, when = 0, hp = 200, lp = 5000, sweep = 0, send = 0 }) {
    if (!this.ready || this.muted || !this.noiseBuf) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.setValueAtTime(lp, t);
    if (sweep) f.frequency.exponentialRampToValueAtTime(Math.max(80, lp + sweep), t + dur);
    f.Q.value = 0.9;
    const hpf = ctx.createBiquadFilter(); hpf.type = 'highpass'; hpf.frequency.value = hp;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(hpf).connect(f).connect(g).connect(this.sfxBus);
    if (send) { const s = ctx.createGain(); s.gain.value = send; g.connect(s).connect(this.delay); }
    src.start(t); src.stop(t + dur + 0.05);
  }

  // ---------- game sounds ----------
  ui() {
    this.tone({ freq: 660, dur: 0.08, type: 'triangle', gain: 0.055, slide: 140, send: 0.15 });
  }

  attach() {
    this.noise({ dur: 0.16, gain: 0.06, hp: 700, lp: 1400, sweep: 2400, send: 0.12 });
    this.tone({ freq: 190, dur: 0.18, type: 'triangle', gain: 0.075, slide: 320 });
  }

  release() {
    this.noise({ dur: 0.28, gain: 0.075, hp: 240, lp: 5200, sweep: -3600, send: 0.1 });
    this.tone({ freq: 320, dur: 0.15, type: 'sine', gain: 0.04, slide: -120 });
  }

  pickup(step = 0) {
    const note = 64 + PENTA[step % PENTA.length];
    const f = midi(note);
    this.tone({ freq: f, dur: 0.4, type: 'triangle', gain: 0.12, send: 0.5, slide: 8 });
    this.tone({ freq: f * 2, dur: 0.25, type: 'sine', gain: 0.05, send: 0.4 });
    this.tone({ freq: f * 1.5, dur: 0.3, type: 'sine', gain: 0.03, send: 0.6, when: 0.015 });
  }

  surgePickup() {
    const chord = [0, 4, 7, 12, 16];
    chord.forEach((n, i) => this.tone({ freq: midi(64 + n), dur: 0.9, type: 'triangle', gain: 0.09, when: i * 0.045, send: 0.5 }));
    this.noise({ dur: 0.6, gain: 0.08, hp: 400, lp: 300, sweep: 6000, send: 0.3 });
  }

  hurt() {
    this.tone({ freq: 130, dur: 0.5, type: 'sawtooth', gain: 0.13, slide: -80, filter: 700 });
    this.tone({ freq: 62, dur: 0.7, type: 'sine', gain: 0.22, slide: -30 });
    this.noise({ dur: 0.4, gain: 0.16, hp: 120, lp: 900, sweep: -600 });
  }

  pop() {
    this.tone({ freq: 480, dur: 0.16, type: 'square', gain: 0.05, slide: -360, filter: 1800 });
    this.noise({ dur: 0.18, gain: 0.08, hp: 600, lp: 2400, sweep: -1400 });
  }

  waveClear() {
    [60, 64, 67, 71, 74, 79].forEach((n, i) => {
      this.tone({ freq: midi(n), dur: 0.75, type: 'triangle', gain: 0.085, when: i * 0.075, send: 0.55 });
    });
    this.noise({ dur: 0.9, gain: 0.06, hp: 700, lp: 800, sweep: 7000, send: 0.35 });
  }

  victory() {
    const seq = [60, 64, 67, 71, 74, 79, 83, 86];
    seq.forEach((n, i) => {
      this.tone({ freq: midi(n), dur: 1.4, type: 'triangle', gain: 0.09, when: i * 0.11, send: 0.6 });
      this.tone({ freq: midi(n - 12), dur: 1.2, type: 'sine', gain: 0.05, when: i * 0.11 });
    });
    [48, 55, 60, 64].forEach((n, i) => this.tone({ freq: midi(n), dur: 3.4, type: 'sawtooth', gain: 0.025, when: i * 0.02, filter: 800 }));
  }

  gameOver() {
    this.tone({ freq: 180, dur: 2.4, type: 'sawtooth', gain: 0.08, slide: -130, filter: 550 });
    this.tone({ freq: 90, dur: 2.8, type: 'sine', gain: 0.16, slide: -55 });
    this.noise({ dur: 1.6, gain: 0.09, hp: 80, lp: 1200, sweep: -1000, send: 0.3 });
  }

  warn() {
    this.tone({ freq: 880, dur: 0.09, type: 'square', gain: 0.02, send: 0.2 });
  }

  // ---------- ambient score ----------
  buildPad() {
    const ctx = this.ctx;
    const bus = ctx.createGain();
    bus.gain.value = 0.0;
    bus.connect(this.musicBus);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass'; filter.frequency.value = 420; filter.Q.value = 0.6;
    filter.connect(bus);
