      p.y += p.vy * dt;
      const d = Math.exp(-p.drag * dt);
      p.vx *= d; p.vy *= d;
    }
  }
}

export function updateTexts(g, dt) {
  for (let i = g.texts.length - 1; i >= 0; i--) {
    const t = g.texts[i];
    t.life -= dt;
    t.y += t.vy * dt;
    t.vy *= Math.exp(-2 * dt);
    if (t.life <= 0) g.texts.splice(i, 1);
